const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfoAsync(eeObject) {
  return await new Promise((resolve, reject) => {
    eeObject.getInfo((res, err) => {
      if (err) reject(err);
      else resolve(res);
    });
  });
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const centralValley = ee.Geometry.Polygon([
      [[-122.9, 39.9], [-118.0, 39.9], [-118.0, 35.0], [-122.9, 35.0], [-122.9, 39.9]]
    ]);
    const octStart = '2022-10-01';
    const octEnd = '2022-11-01';
    const marStart = '2023-03-01';
    const marEnd = '2023-04-01';

    // 2. Data Acquisition & Check with fallback datasets
    const candidates = [
      'NASA/GRACE/MASS_GRIDS/LAND/CSR',
      'NASA/GRACE/MASS_GRIDS/LAND/JPL',
      'NASA/GRACE/MASS_GRIDS/LAND/GFZ'
    ];

    let chosen = null;
    let sizes = null;

    for (const ds of candidates) {
      const colOct = ee.ImageCollection(ds).filterDate(octStart, octEnd).select('lwe_thickness');
      const colMar = ee.ImageCollection(ds).filterDate(marStart, marEnd).select('lwe_thickness');
      const nOct = await getInfoAsync(colOct.size());
      const nMar = await getInfoAsync(colMar.size());
      console.log(`Try ${ds} -> Oct imgs: ${nOct}, Mar imgs: ${nMar}`);
      if (nOct > 0 && nMar > 0) {
        chosen = ds;
        sizes = { nOct, nMar };
        break;
      }
    }

    if (!chosen) {
      console.log('No images found for one or both periods.');
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      console.log('C1');
      return;
    }

    // 3. Processing: compute monthly means and pixel counts
    const colOct = ee.ImageCollection(chosen).filterDate(octStart, octEnd).select('lwe_thickness');
    const colMar = ee.ImageCollection(chosen).filterDate(marStart, marEnd).select('lwe_thickness');

    const imgOct = colOct.mean();
    const imgMar = colMar.mean();

    const countDictOct = imgOct.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: centralValley,
      scale: 30000,
      maxPixels: 1e9
    });
    const countDictMar = imgMar.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: centralValley,
      scale: 30000,
      maxPixels: 1e9
    });

    const pixOct = await getInfoAsync(countDictOct.get('lwe_thickness'));
    const pixMar = await getInfoAsync(countDictMar.get('lwe_thickness'));

    if (!pixOct || !pixMar || pixOct === 0 || pixMar === 0) {
      console.log(`Dataset: ${chosen}`);
      console.log(`Oct 2022 Images: ${sizes.nOct}, Valid Pixels: ${pixOct || 0}`);
      console.log(`Mar 2023 Images: ${sizes.nMar}, Valid Pixels: ${pixMar || 0}`);
      console.log('C2: No Valid Pixels (Images exist, but after masking/processing, 0 pixels remain).');
      console.log('C2');
      return;
    }

    // 4. Calculation: mean LWE (cm)
    const meanDictOct = imgOct.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: centralValley,
      scale: 30000,
      maxPixels: 1e9
    });
    const meanDictMar = imgMar.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: centralValley,
      scale: 30000,
      maxPixels: 1e9
    });

    const meanOct = await getInfoAsync(meanDictOct.get('lwe_thickness'));
    const meanMar = await getInfoAsync(meanDictMar.get('lwe_thickness'));

    // 5. Validation & Final Answer
    const invalid =
      meanOct === null || meanMar === null ||
      !isFinite(meanOct) || !isFinite(meanMar) ||
      Math.abs(meanOct) > 500 || Math.abs(meanMar) > 500;

    console.log(`Dataset: ${chosen}`);
    console.log(`Oct 2022 -> Images: ${sizes.nOct}, Mean LWE (cm): ${meanOct !== null ? meanOct.toFixed(2) : 'null'}, Pixels: ${pixOct}`);
    console.log(`Mar 2023 -> Images: ${sizes.nMar}, Mean LWE (cm): ${meanMar !== null ? meanMar.toFixed(2) : 'null'}, Pixels: ${pixMar}`);

    if (invalid) {
      console.log('C3: Calculation Failure (Result is None/NaN/invalid).');
      console.log('C3');
      return;
    }

    const diff = meanOct - meanMar;
    console.log(`Difference (Oct 2022 - Mar 2023) [cm]: ${diff.toFixed(2)}`);

    if (diff > 0) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
